window.LAW_DATA = {"id": "maglis-dawla", "title": "قانون مجلس الدولة", "title_en": "STATE COUNCIL", "cat": "عمل وإداري", "icon": "🏛️", "desc": "القانون رقم 47 لسنة 1972 — اختصاصات القضاء الإداري وأقسام الفتوى والتشريع.", "article_count": 128, "articles": [{"number": "1", "chapter": "", "text": "مجلس الدولة هيئة قضائية مستقلة"}, {"number": "2", "chapter": "", "text": "يتكون مجلس الدولة من : أ- القسم القضائي ب- قسم الفتوى ج- قسم التشريع ويشكل المجلس من رئيس ومن عدد كاف من نواب الرئيس والوكلاء والمستشارين ومن المستشارين المساعدين والنواب والمندوبين . ويلحق بالمجلس مندوبون مساعدون تسرى عليهم الأحكام الخاصة بالمندوبين عدا شرط الحصول على دبلومتين من دبلومات الدراسات العليا ."}, {"number": "3", "chapter": "الباب الأول القسم القضائي الفصل الأول الترتيب والتشكيل", "text": "يؤلف القسم القضائي من : أ - المحكمة الإدارية العليا ب- محكمة القضاء الإداري ج- المحاكم الإدارية د - المحاكم التأديبية هـ- هيئة مفوضي الدولة"}, {"number": "4", "chapter": "الباب الأول القسم القضائي الفصل الأول الترتيب والتشكيل", "text": "يكون مقر المحكمة الإدارية العليا فى القاهرة ويرأسها رئيس المجلس وتصدر أحكامها من دوائر من خمسة مستشارين وتكون بها دائرة أو أكثر لفحص الطعون وتشكل من ثلاثة مستشارين . ويكون مقر محكمة القضاء الإداري مدينة القاهرة ويرأسها نائب رئيس المجلس لهذه المحكمة وتصدر أحكامها من دوائر تشكل كل منها من ثلاثة مستشارين ، ويحدد اختصاص كل دائرة من دوائر محكمة القضاء الإدارى بقرار من رئيس مجلس الدولة . ويجوز بقرار من رئيس مجلس الدولة إنشاء دوائر للقضاء الإدارى فى المحافظات الأخرى وإذا شمل اختصاص الدائرة أكثر من محافظة جاز لها – بقرار من رئيس المجلس – أن تعقد جلساتها فى عاصمة أى من المحافظات الداخلة فى دائرة اختصاصها ."}, {"number": "5", "chapter": "الباب الأول القسم القضائي الفصل الأول الترتيب والتشكيل", "text": "يكون مقر المحاكم الإدارية فى القاهرة والإسكندرية ، ويكون لهذه المحاكم نائب رئيس يعاون رئيس المجلس فى القيام على تنظيمها وحسن سير العمل بها . ويجوز إنشاء محاكم إدارية فى المحافظات الأخرى بقرار من رئيس المجلس ، وتصدر أحكامها من دوائر تشكل كل منها برئاسة مستشار مساعد وعضوية اثنين من النواب على الأقل ، وتحدد دائرة اختصاص كل محكمة بقرار من رئيس مجلس الدولة وإذا شمل اختصاص المحكمة أكثر من محافظة جاز لها أن تنعقد فى عاصمة أى محافظة من المحافظات الداخلة فى اختصاصها وذلك بقرار من رئيس مجلس الدولة ."}, {"number": "6", "chapter": "الباب الأول القسم القضائي الفصل الأول الترتيب والتشكيل", "text": "تؤلف هيئة مفوضي الدولة من أحد نواب رئيس المجلس رئيسا ومن عدد كاف من المستشارين والمستشارين المساعدين والنواب والمندوبين . ويكون مفوضو الدولة لدى المحكمة الإدارية العليا ومحكمة القضاء الإدارى من درجة مستشار مساعد على الأقل ."}, {"number": "7", "chapter": "الباب الأول القسم القضائي الفصل الأول الترتيب والتشكيل", "text": "تتكون المحاكم التأديبية من : 1- المحاكم التأديبية للعاملين من مستوى الإدارة العليا ومن يعادلهم 2- المحاكم التأديبية للعاملين من المستويات الأول والثانى والثالث ومن يعادلهم . ويكون لهذه المحاكم نائب لرئيس المجلس يعاون رئيس المجلس فى القيام على شئونها ."}, {"number": "8", "chapter": "الباب الأول القسم القضائي الفصل الأول الترتيب والتشكيل", "text": "يكون مقر المحاكم التأديبية للعاملين من مستوى الإدارة العليا فى القاهرة والإسكندرية وتؤلف من دائرة أو أكثر تشكل كل منها من ثلاثة مستشارين ويكون مقار المحاكم التأديبية للعاملين من المستويات الأول والثاني والثالث فى القاهرة والإسكندرية وتؤلف من دوائر تشكل كل منها برئاسة مستشار مساعد على الأقل ، وعضوية اثنين من النواب على الأقل ، ويصدر بالتشكيل قرار من رئيس المجلس. ويجوز بقرار من رئيس مجلس الدولة إنشاء محاكم تأديبية فى المحافظات الأخرى القرار عددها ومقارها ودوائر اختصاصها بعد أخذ رأى مدير النيابة الإدارية . وإذا شمل اختصاص المحكمة التأديبية أكثر من محافظة جاز لها أن تنعقد فى عاصمة أى محافظة من المحافظات الداخلة فى اختصاصها ، وذلك بقرار من رئيس مجلس الدولة"}, {"number": "9", "chapter": "الباب الأول القسم القضائي الفصل الأول الترتيب والتشكيل", "text": "يتولى أعضاء النيابة الإدارية الإدعاء أمام المحاكم التأديبية ."}, {"number": "10", "chapter": "الفصل الثاني الاختصاصات", "text": "تختص محاكم مجلس الدولة دون غيرها بالفصل فى المسائل الآتية : أولاً : الطعون الخاصة بانتخابات المجالس المحلية . ثانياً : المنازعات الخاصة بالمرتبات والمعاشات والمكافآت المستحقة للموظفين العموميين أو لورثتهم . ثالثاً : الطلبات التي يقدمها ذوو الشأن بالطعن فى القرارات الإدارية النهائية الصادرة بالتعيين فى الوظائف العامة أو الترقية أو بمنح العلاوات رابعاً : الطلبات التى يقدمها الموظفون العموميون بإلغاء القرارات الإدارية الصادرة بإحالتهم إلى المعاش أو الاستيداع أو فصلهم بغير الطريق التأديبى . خامساً : الطلبات التى يقدمها الأفراد أو الهيئات بإلغاء القرارات الإدارية النهائية . سادساً : الطعون فى القرارات النهائية الصادرة من الجهات الإدارية فى منازعات الضرائب والرسوم وفقاً للقانون الذي ينظم كيفية نظر هذه المنازعات أمام مجلس الدولة . سابعاً : دعاوى الجنسية . ثامناً : الطعون التى ترفع عن القرارات النهائية الصادرة من جهات إدارية لها اختصاص قضائى ، فيما عدا القرارات الصادرة من هيئات التوفيق والتحكيم فى منازعات العمل وذلك متى كان مرجع الطعن ، عدم الاختصاص أو عيبا فى الشكل أو مخالفة للقوانين واللوائح أو الخطأ فى تطبيقها أو تأويلها . تاسعاً : الطلبات التى يقدمها الموظفون العموميين بإلغاء القرارات النهائية للسلطات التأديبية . عاشراً : طلبات التعويض عن القرارات المنصوص عليها فى البنود السابقة سواء رفعت بصفة أصلية أو تبعية . حادي عشر : المنازعات الخاصة بعقود الالتزام أو الأشغال العامة أو التوريد أو بأى عقد إداري آخر . ثاني عشر : الدعاوى التأديبية المنصوص عليها فى هذا القانون ثالث عشر : الطعون فى الجزاءات الموقعة على العاملين بالقطاع العام فى الحدود المقررة قانوناً . رابع عشر : سائر المنازعات الإدارية . ويشترط فى طلبات إلغاء القرارات الإدارية النهائية أن يكون مرجع الطعن عدم الاختصاص أو عيبا فى الشكل أو مخالفة القوانين أو اللوائح أو الخطأ فى تطبيقها أو تأويلها أو إساءة استعمال السلطة . ويعتبر فى حكم القرارات الإدارية رفض السلطات الإدارية أو امتناعها عن اتخاذ قرار كان من الواجب عليها اتخاذه وفقا للقوانين واللوائح ."}, {"number": "11", "chapter": "الفصل الثاني الاختصاصات", "text": "لاتختص محاكم مجلس الدولة بالنظر فى الطلبات المتعلقة بإعمال السيادة ."}, {"number": "12", "chapter": "الفصل الثاني الاختصاصات", "text": "لاتقبل الطلبات الآتية : أ ) الطلبات المقدمة من أشخاص ليست لهم فيها مصلحة شخصية ب) الطلبات المقدمة رأسا بالطعن فى القرارات الإدارية النهائية المنصوص عليها فى البنود ثالثا ورابعا وتاسعا من المادة 10 وذلك فبل التظلم منها إلى الهيئة الإدارية التى أصدرت القرار أو إلى الهيئات الرئاسية وانتظار المواعيد المقررة للبت فى هذا التظلم ، وتبين إجراءات التظلم وطريقة الفصل فيه بقرار من رئيس مجلس الدولة . أولا : اختصاص محكمة القضاء الإدارى"}, {"number": "13", "chapter": "الفصل الثاني الاختصاصات", "text": "تختص محكمة القضاء الإدارى بالفصل فى المسائل المنصوص عليها فى المادة 10 عدا ما تختص به المحاكم الإدارية والمحاكم التأديبية كما تختص بالفصل فى الطعون التى ترفع إليها عن الأحكام الصادرة من المحاكم الإدارية ، ويكون الطعن من ذوى الشأن أو من رئيس هيئة مفوضي الدولة وذلك خلال ستين يوماً من تاريخ صدور الحكم . ثانيا : اختصاص المحاكم الإدارية"}, {"number": "14", "chapter": "الفصل الثاني الاختصاصات", "text": "تختص المحاكم الإدارية : 1. بالفصل فى طلبات إلغاء القرارات المنصوص عليها فى البنود ثالثا ورابعا من المادة 10 متى كانت متعلقة بالموظفين العموميين من المستوى الثانى والمستوى الثالث ومن يعادلهم ، وفى طلبات التعويض المترتبة على هذه القرارات . 2. بالفصل فى المنازعات الخاصة بالمرتبات والمعاشات والمكافآت والمستحقة لمن ذكروا فى البند السابق أو لورثتهم . 3. بالفصل فى المنازعات الواردة فى البند الحادي عشر من المادة 10 متى كانت قيمة المنازعة لا تجاوز خمسمائة جنيه . ثالثا : اختصاص المحاكم التأديبية"}, {"number": "15", "chapter": "الفصل الثاني الاختصاصات", "text": "تختص المحاكم التأديبية بنظر الدعاوى التأديبية عن المخالفات المالية والإدارية التى تقع من : أولاً : العاملين المدنيين بالجهاز الإدارى للدولة فى وزارات الحكومة ومصالحها ووحدات الحكم المحلى والعاملين بالهيئة العامة والمؤسسات العامة وما يتبعها من وحدات وبالشركات التى تضمن لها الحكومة حدا أدنى من الأرباح . ثانياً : أعضاء مجالس إدارة التشكيلات النقابية المشكلة طبقا لقانون العمل وأعضاء مجالس الإدارة المنتخبين طبقاً لأحكام القانون رقم 141 لسنة 1983 ، المشار إليه . ثالثاً : العاملين بالجمعيات والهيئات الخاصة التى يصدر بتحديدها قرار من رئيس الجمهورية ممن تجاوز مرتباتهم خمسة عشر جنيهاً شهرياً كما تختص هذه المحاكم بنظر الطعون المنصوص عليها فى البندين تاسعا وثالث عشر من المادة العاشرة"}, {"number": "16", "chapter": "الفصل الثاني الاختصاصات", "text": "يصدر رئيس المحكمة قرارا بالفصل فى طلبات وقف أو مد وقف الأشخاص المشار إليهم فى المادة السابقة عن العمل أو صرف المرتب كله أو بعضه أثناء مدة الوقف وذلك فى الحدود المقررة قانونا ."}, {"number": "17", "chapter": "الفصل الثاني الاختصاصات", "text": "يتحدد اختصاص المحكمة التأديبية تبعا للمستوى الوظيفى للعامل وقت الدعوى وإذا تعدد العاملون المقدمون للمحكمة المختصة بمحاكمة أعلاهم فى المستوى الوظيفي هى المختصة بمحاكمتهم جميعا . ومع ذلك تختص المحكمة التأديبية للعاملين من المستوى الأول والثانى والثالث بمحاكمة جميع العاملين بالجمعيات والشركات والهيئات الخاصة المنصوص عليها فى المادة ( 15 ) ."}, {"number": "18", "chapter": "الفصل الثاني الاختصاصات", "text": "تكون محاكمة العاملين المنسوبة إليهم مخالفة واحدة أو مخالفات مرتبطة ببعضها ومجازاتهم أمام المحكمة التى وقعت فى دائرة اختصاصها المخالفة أو المخالفات المذكورة ، فإذا تعذر تعيين المحكمة عينها رئيس مجلس الدولة بقرار منه ."}, {"number": "19", "chapter": "الفصل الثاني الاختصاصات", "text": "توقع المحاكم التأديبية الجزاءات المنصوص عليها فى القوانين المنظمة لشئون من تجرى محاكمتهم . على أنه بالنسبة إلى العاملين بالجمعيات والهيئات الخاصة التى يصدر بتحديدها قرار من رئيس الجمهورية والعاملين بالشركات التى تضمن لها الحكومة حدا أدنى من الأرباح فتكون الجزاءات : الإنذار الخصم من المرتب لمدة لا تجاوز شهرين . خفض المرتب . تنزيل الوظيفة . العزل من الوظيفة مع حفظ الحق فى المعاش أو المكافأة أو مع الحرمان من المعاش أو المكافأة وذلك فى حدود الربع ."}, {"number": "20", "chapter": "الفصل الثاني الاختصاصات", "text": "لاتجوز إقامة الدعوى التأديبية على العاملين بعد انتهاء خدمتهم إلا فى الحالتين الآتيتين : إذا كان قد بدئ فى التحقيق أو المحاكمة قبل انتهاء الخدمة . إذا كانت المخالفة من المخالفات المالية التى يترتب عليها ضياع حق من الحقوق المالية للدولة أو أحد الأشخاص الاعتبارية العامة أو الوحدات التابعة لها وذلك لمدة خمس سنوات من تاريخ انتهاء الخدمة ولو لم يكن قد بدئ فى التحقيق قبل ذلك ."}, {"number": "21", "chapter": "الفصل الثاني الاختصاصات", "text": "الجزاءات التأديبيـة التى يجوز للمحاكم التأديبية توقيعها على من ترك الخدمة هي : 1.غرامة لا تقل عن خمسة جنيهات ولا تجاوز الأجر الإجمالي الذي كان يتقاضاه العامل فى الشهر الذي وقعت فيه المخالفة. 2. الحرمان من المعاش مدة لا تزيد على 3 أشهر . الحرمان من المعاش فيما لا يجاوز الربع . وفى جميع الأحوال يجوز للمحكمة التأديبية فى أى مرحلة من مراحل التحقيق أو الدعوى وقف صرف جزء من المعاش أو المكافأة بما لا يجاوز الربع إلى حين انتهاء المحاكمة . ويستوفى المبلغ المنصوص عليه فى البندين 1 ، 2 بالخصم من المعاش فى حدود الربع شهريا أو من المكافأة أو المال المدخر أن وجد أو بطريق الحجز الإدارى ."}, {"number": "22", "chapter": "الفصل الثاني الاختصاصات", "text": "أحكام المحاكم التأديبية نهائية ويكون الطعن فيها أمام المحكمة الإدارية العليا فى الأحوال المبينة فى هذا القانون . ويعتبر من ذوى الشأن فى الطعن الوزير المختص ورئيس الجهاز المركزى للمحاسبات ومدير النيابة الإدارية . وعلى رئيس هيئة مفوضي الدولة بناء على طلب من العامل المفصول أن يقيم الطعن فى حالات الفصل من الوظيفة . رابعا : اختصاص المحكمة الإدارية العليا يجوز الطعن أمام المحكمة الإدارية العليا فى الأحكام الصادرة من محكمة القضاء الإدارى أو من المحاكم التأديبية وذلك فى الأحوال الآتية : 1. إذا كان الحكم المطعون فيه مبنيا على مخالفة القانون أو خطأ فى تطبيقه أو تأويله . 2. إذا وقع بطلان فى الحكم أو بطلان فى الإجراءات أثر فى الحكم 3. إذا صدر الحكم على خلاف حكم سابق حاز قوة الشئ المحكوم فيه سواء دفع بهذا الدفع أو لم يدفع . ويكون لذوى الشأن ولرئيس هيئة مفوضى الدولة أن يطعن فى تلك الأحكام خلال ستين يوماً من تاريخ صدور الحكم وذلك مع مراعاة الأحوال التى يوجب عليه القانون فيها الطعن فى الحكم . أما الأحكام الصادرة من محكمة القضاء الإدارى فى الطعون المقامة أمامها فى أحكام المحاكم الإدارية فلا يجوز الطعن فيها أمام المحكمة الإدارية العليا إلا من رئيس مفوضي الدولة خلال ستين يوما من تاريخ صدور الحكم وذلك إذا صدر الحكم على خلاف ما جرى عليه قضاء المحكمة الإدارية العليا أو إذا كان الفصل فى الطعن يقتضي تقرير مبدأ قانوني لم يسبق لهذه المحكمة تقريره . الفصل الثالث الإجراءات أولاً : الإجراءات أمام محكمة القضاء الإدارى والمحاكم الإدارية"}, {"number": "24", "chapter": "الفصل الثاني الاختصاصات", "text": "ميعاد رفع الدعوى أمام المحكمة فيما يتعلق بطلبات الإلغاء ستون يوما من تاريخ نشر القرار الإدارى المطعون فيه فى الجريدة الرسمية أو فى النشرات التى تصدرها المصالح العامة أو إعلان صاحب الشأن به . وينقطع سريان هذا الميعاد بالتظلم إلى الهيئة الإدارية التى أصدرت القرار أو الهيئات الرئاسية ، ويجب أن يبت فى التظلم قبل مضى ستين يوما من تاريخ تقديمه ، وإذا صدر القرار بالرفض وجب أن يكون مسببا ويعتبر مضى ستين يوما على تقديم التظلم دون أن تجيب عنه السلطات المختصة بمثابة رفضه . ويكون ميعاد رفع الدعوى بالطعن فى القرار الخاص بالتظلم ستين يوما من تاريخ انقضاء الستين يوما المذكورة ."}, {"number": "25", "chapter": "الفصل الثاني الاختصاصات", "text": "يقدم الطلب إلى قلم كتاب المحكمة المختصة بعريضة موقعة من محام مقيد بجدول المحامين المقبولين أمام تلك المحكمة وتتضمن العريضة عدا البيانات العامة المتعلقة باسم الطالب ومن يوجه إليهم الطلب وصفاتهم ومحال إقامتهم موضوع الطلب وتاريخ التظلم من القرار أن كان مما يوجب التظلم منه ونتيجة التظلم وبيانا بالمستندات المؤيدة للطلب ويرفق بالعريضة صورة أو ملخص من القرار المطعون فيه . وللطالب أن يقدم مع العريضة مذكرة يوضح فيها أسانيد الطلب وعليه أن يودع قلم كتاب المحكمة عدا الأصول عددا كافيا من صور العريضة والمذكرة وحافظة بالمستندات . وتعلن العريضة ومرفقاتها إلى الجهة الإدارية المختصة وإلى ذوى الشأن فى ميعاد لا يجاوز سبعة أيام من تاريخ تقديمها ويتم الإعلان بطريق البريد بخطاب موصى عليه مصحوب بعلم الوصول . ويعتبر مكتب المحامى الموقع على العريضة محلا للطالب كما يعتبر مكتب المحامى الذي ينوب عن ذوى الشأن فى تقديم ملاحظاتهم محلا مختارا لهم ، كل ذلك إلا إذا عينوا محلا مختارا غيره ."}, {"number": "26", "chapter": "الفصل الثاني الاختصاصات", "text": "على الجهة الإدارية المختصة أن تودع قلم كتاب المحكمة خلال ثلاثين يوما من تاريخ إعلانها مذكرة بالبيانات والملاحظات المتعلقة بالدعوى مشفوعة بالمستندات والأوراق الخاصة بها . ويكون للطالب أن يودع قلم كتاب المحكمة مذكرة بالرد مشفوعة بما يكون لديه من مستندات فى المهلة التى يحددها له المفوض إذا رأى وجها لذلك فإذا استعمل الطالب حقه فى الرد كان للجهة الإدارية أن تودع مذكرة بملاحظاتها على هذا الرد مع مستندات فى مدة مماثلة ويجوز لرئيس المحكمة فى أحوال الاستعجال أن يصدر أمرا غير قابل للطعن بتقصير الميعاد المبين فى الفقرة الأولى من هذه المادة ويعلن الأمر إلى ذوى الشأن خلال أربع وعشرين ساعة من تاريخ صدوره وذلك بطريق البريد أويسرى الميعاد المقصر من تاريخ الإعلان . ويقوم قلم كتاب المحكمة خلال أربعة وعشرين ساعة من انقضاء الميعاد فى الفقرة الأولى بإرسال ملف الأوراق إلى هيئة مفوضى الدولة بالمحكمة ."}, {"number": "27", "chapter": "الفصل الثاني الاختصاصات", "text": "تتولى هيئة مفوضي الدولة تحضير الدعوى وتهيئتها للمرافعة ولمفوض الدولة فى سبيل تهيئة الدعوى الاتصال بالجهات الحكومية ذات الشأن للحصول على ما يكون لازما من بيانات وأوراق وأن يأمر باستدعاء ذوى الشأن لسؤالهم عن الوقائع التى يرى لزم تحقيقها أو بدخول شخص ثالث فى الدعوى أو بتكليف ذوى الشأن بتقديم مذكرات أو مستندات تكميلية وغير ذلك من إجراءات التحقيق فى الأجل الذي يحدده لذلك . ولايجوز فى سبيل تهيئة الدعوى تكرار التأجيل لسبب واحد . ومع ذلك يجوز للمفوض إذا رأى منح أجل جديد أن يحكم على طالب التأجيل بغرامة لا تجاوز عشرة جنيهات يجوز منحها للطرف الآخر ويودع المفوض – بعد إتمام تهيئة الدعوى – تقريرا يحدد فيه الوقائع والمسائل القانونية التى يثيرها النزاع ويبدى رأيه مسببا ، ويجوز لذوى الشأن أن يطلعوا على تقرير المفوض بقلم كتاب المحكمة ولهم أن يطلبوا صورة منه على نفقتهم . ويفصل المفوض فى طلبات الإعفاء من الرسوم ."}, {"number": "28", "chapter": "الفصل الثاني الاختصاصات", "text": "لمفوض الدولة أن يعرض على الطرفين تسوية النزاع على أساس المبادئ القانونية التى ثبت عليها قضاء المحكمة الإدارية العليا فى خلال أجل يحدده فإن تمت التسوية أثبتت فى محضر يوقع من الخصوم أو وكلائهم ، وتكون للمحضر فى هذه الحالة قوة السند التنفيذي ، وتعطى صورته وفقاً للقواعد المقررة لإعطاء صور الأحكام ، وتستبعد القضية من الجدول لانتهاء النزاع فيها ، وإن لم تتم التسوية جاز للمحكمة عند الفصل فى الدعوى أن تحكم على المعترض على التسوية بغرامة لا تجاوز عشرين جنيها ويجوز منحها للطرف الآخر"}, {"number": "29", "chapter": "الفصل الثاني الاختصاصات", "text": "تقوم هيئة مفوضي الدولة خلال ثلاثة أيام من تاريخ إيداع التقرير المشار إليه فى المادة 27 بعرض ملف الأوراق على رئيس المحكمة لتعيين تاريخ الجلسة التى تنظر فيها الدعوى ."}, {"number": "30", "chapter": "الفصل الثاني الاختصاصات", "text": "يكون توزيع القضية على دوائر المحكمة بمراعاة نوعها طبقاً للنظام الذي تبينه اللائحة الداخلية للمجلس . ويبلغ قلم كتاب المحكمة تاريخ الجلسة إلى ذوى الشأن ويكون ميعاد الحضور ثمانية أيام على الأقل ويجوز فى حالة الضرورة تقصيره إلى ثلاثة أيام ."}, {"number": "31", "chapter": "الفصل الثاني الاختصاصات", "text": "لرئيس المحكمة أن يطلب إلى ذوى الشأن أو إلى المفوض ما يراه لازما من إيضاحات . ولا تقبل المحكمة أى دفع أو طلب أو أوراق مما كان يلزم تقديمه قبل إحالة القضية إلى الجلسة إلا إذا ثبت لها أن أسباب ذلك الدفع أو الطلب أو تقديم تلك الورقة طرأت بعد الإحالة أو كان الطالب يجهلها عند الإحالة . ومع ذلك إذا رأت المحكمة تحقيقا للعدالة قبول دفع أو طلب ورقة جديدة جاز لها ذلك مع جواز الحكم على الطرف الذى وقع منه الإهمال بغرامة لا تجاوز عشرين جنيها يجوز منحها للطرف الآخر ، على أن الدفوع والأسباب المتعلقة بالنظام العام يجوز إبداؤها فى أى وقت كما يجوز للمحكمة أن تقضى بها من تلقاء نفسها."}, {"number": "32", "chapter": "الفصل الثاني الاختصاصات", "text": "وإذا رأت المحكمة ضرورة إجراء تحقيق باشرته بنفسها فى الجلسة أو قام به من تندبه لذلك من أعضائها أو من المفوضين ."}, {"number": "33", "chapter": "الفصل الثاني الاختصاصات", "text": "ويصدر الحكم فى الدعوى فى جلسة علنية . ثانياً : الإجراءات أمام المحاكم التأديبية"}, {"number": "34", "chapter": "الفصل الثاني الاختصاصات", "text": "تقام الدعوى التأديبية من النيابة الإدارية بإيداع أوراق التحقيق وقرار الإحالة قلم كتاب المحكمة المختصة ، ويجب أن يتضمن القرار المذكور بيانا بأسماء العاملين وفئاتها والمخالفات المنسوبة إليهم والنصوص القانونية الواجبة التطبيق . وتنظر الدعوى فى جلسة تعقد خلال خمسة عشر يوما من تاريخ إيداع هذه الأوراق قلم كتاب المحكمة ، ويتولى رئيس المحكمة تحديدها خلال الميعاد المذكور على أن يقوم قلم كتاب المحكمة بإعلان ذوى الشأن بقرار الإحالة وتاريخ الجلسة خلال أسبوع من تاريخ إيداع الأوراق . ويكون الإعلان فى محل إقامة المعلن إليه أو فى محل عمله بخطاب موصى عليه مصحوب بعلم الوصول . ويتم إعلان أفراد القوات المسلحة ومن فى حكمهم – ممن تسرى فى شأنهم أحكام هذا القانون – بتسليمه إلى الإدارة القضائية المختصة بالقوات المسلحة"}, {"number": "35", "chapter": "الفصل الثاني الاختصاصات", "text": "تفصل المحكمة التأديبية فى القضايا التى تحال إليها على وجه السرعة وعلى الوزراء والرؤساء المختصين موافاة المحكمة بما تطلبه من بيانات أو ملفات أو أوراق لازمة للفصل فى الدعوى خلال أسبوع من تاريخ الطلب . ولايجوز تأجيل نظر الدعوى أكثر من مرة لذات السبب على ألا تجاوز فترة التأجيل أسبوعين . وتصدر المحكمة حكمها فى مدة لا تجاوز شهرين من تاريخ إحالة الدعوى إليها ."}, {"number": "36", "chapter": "الفصل الثاني الاختصاصات", "text": "للمحكمة استجوب العامل المقدم للمحاكمة وسماع الشهود من العاملين وغيرهم ويكون أداء الشهادة أمام المحكمة بعد حلف اليمين ويسرى على الشهود فيما يتعلق بالتخلف عن الحضور والامتناع عن أداء الشهادة أو شهادة الزور الأحكام المقررة لذلك قانونا وتحرر المحكمة محضرا بما يقع من الشاهد وتحيله إلى النيابة العامة إذا رأت فى الأمر جريمة . وإذا كان الشاهد من العاملين الذين تختص المحاكم التأديبية بمحاكمتهم وتخلف عن الحضور بعد تأجيل الدعوى وإخطاره بالجلسة المحددة مرة أخرى أو امتنع عن أداء الشهادة ، جاز لمحكمة أن تحكم عليه بالإنذار أو الخصم من المرتب لمدة لا تجاوز شهرين ."}, {"number": "37", "chapter": "الفصل الثاني الاختصاصات", "text": "للعامل المقدم إلى المحكمة التأديبية أن يحضر جلسات المحاكمة أو أن يوكل عنه محاميا وله أن يبدى دفاعه كتابة أو شفاهه ، وللمحكمة أن تقر حضوره شخصيا ."}, {"number": "38", "chapter": "الفصل الثاني الاختصاصات", "text": "تتم جميع الإخطارات والإعلانات بالنسبة للدعاوى المنظورة أمام المحاكم التأديبية بالطريقة المنصوص عليها فى المادة ( 34 )."}, {"number": "39", "chapter": "الفصل الثاني الاختصاصات", "text": "إذا رأت المحكمة أن الواقعة التى وردت بأمر الإحالة أو غيرها من الوقائع التى تضمنها التحقيق تكون جريمة جنائية أحالتها إلى النيابة العامة للتصرف فيها وفصلت فى الدعوى التأديبية . ومع ذلك إذا كان الحكم فى دعوى تأديبية تتوقف على نتيجة الفصل فى دعوى جنائية وجب وقف الأولى حتى يتم الفصل فى الثانية . ولايمنع وقف الدعوى من استمرار وقف العمل . وعلى النيابة الإدارية تعجيل نظر الدعوى بمجرد زوال سبب الوقف"}, {"number": "40", "chapter": "الفصل الثاني الاختصاصات", "text": "تفصل المحكمة فى الواقعة التى وردت بقرار الإحالة ، ومع ذلك يجوز للمحكمة سواء من تلقاء نفسها أو بناء على النيابة الإدارية التصدي لوقائع لم ترد فى قرار الإحالة والحكم فيها إذا كانت عناصر المخالفة ثابتة فى الأوراق ، وبشرط أن تمنح العامل أجلا مناسبا لتحضير دفاعه إذا طلب ذلك ."}, {"number": "40", "chapter": "الفصل الثاني الاختصاصات", "text": "للمحكمة أن تقيم الدعوى على عاملين من غير من قدموا للمحاكمة أمامها إذا قامت لديها أسباب جدية بوقوع مخالفة منهم ، وفى هذه الحالة يجب منحهم أجلا مناسبا لتحضير دفاعهم إذا طلبوا ذلك ، وتحال الدعوى برمتها إلى دائرة أخرى بقرار من رئيس مجلس الدولة بناء على طلب رئيس المحكمة ."}, {"number": "42", "chapter": "الفصل الثاني الاختصاصات", "text": "مع مراعاة ما هو منصوص عليه فى قانون نظام العاملين بالقطاع العام المشار إليه يعمل عند نظر الطعون المنصوص عليها فى البند الثالث عشر من المادة العاشرة بالقواعد والإجراءات والمواعيد المنصوص عليها فى الفصل الثالث – أولا – من الباب الأول من هذا القانون عدا الأحكام المتعلقة بهيئة مفوضى الدولة"}, {"number": "43", "chapter": "الفصل الثاني الاختصاصات", "text": "لايجوز تأجيل النطق بالحكم أكثر من مرة ، وتصدر الأحكام مسببة يوقعها الرئيس والأعضاء . ثالثاً : الإجراءات أمام المحكمة الإدارية العليا"}, {"number": "44", "chapter": "الفصل الثاني الاختصاصات", "text": "ميعاد رفع الطعن إلى المحكمة الإدارية العليا ستون يوما من تاريخ صدور الحكم المطعون فيه . ويقدم الطعن من ذوى الشأن بتقرير يودع قلم كتاب المحكمة موقع من محامى من المقبولين أمامها ويجب أن يشتمل التقرير علاوة على البيانات العامة المتعلقة بأسماء الخصوم وصفاتهم وموطن كل منهم – على بيان الحكم المطعون فيه وتاريخه وبيان بالأسباب التى بنى عليها الطعن وطلبات الطاعن فإذا لم يحصل الطعن على هذا الوجه جاز الحكم ببطلانه ويجب على ذوى الشأن عند التقرير بالطعن أن يودعوا خزانة المجلس كفالة مقدارها عشرة جنيهات تقضى دائرة فحص الطعون بمصادرتها فى حالة الحكم برفض الطعن ، ولا يسرى هذا الحكم على الطعون التي ترفع من الوزير المختص وهيئة مفوضى الدولة ورئيس الجهاز المركزي للمحاسبات ومدير النيابة الإدارية."}, {"number": "45", "chapter": "الفصل الثاني الاختصاصات", "text": "يجب على قلم كتاب المحكمة ضم ملف الدعوى المطعون فى الحكم الصادر فيها قبل إحالتها إلى هيئة فوضى الدولة ."}, {"number": "46", "chapter": "الفصل الثاني الاختصاصات", "text": "تنظر دائرة فحص الطعون الطعن بعد سماع إيضاحات مفوضى الدولة وذوى الشأن إن رأى رئيس الدائرة وجها لذلك وإذا رأت دائرة فحص الطعون أن الطعن جدير بالعرض على المحكمة الإدارية العليا ، أما لأن الطعن مرجح القبول أو لأن الفصل فى الطعن يقتضي تقرير مبدأ قانوني لم يسبق للمحكمة تقريره أصدرت قرارا بإحالته إليها أما إذا رأت – بإجماع الآراء – أنه غير مقبول شكلاً أو باطل أو غير جدير بالعرض على المحكمة حكمت برفضه . ويكتفى بذكر القرار أو الحكم بمحضر الجلسة ، وتبين المحكمة فى المحضر بإيجاز وجهة النظر إذا كان الحكم صادرا بالرفض ، ولا يجوز الطعن فيه بأى طريق من طرق الطعن . وإذا قررت دائرة فحص الطعون إحالة الطعن إلى المحكمة الإدارية العليا يؤشر قلم كتاب المحكمة بذلك على تقرير الطعن ويخطر ذوو الشأن وهيئة مفوضى الدولة بهذا القرار ."}, {"number": "47", "chapter": "الفصل الثاني الاختصاصات", "text": "تسرى القواعد المقررة لنظر الطعن أمام المحكمة الإدارية العليا على الطعن أمام دائرة فحص الطعون . ويجوز أن يكون من بين أعضاء المحكمة الإدارية العليا من اشترك من أعضاء دائرة فحص الطعون فى إصدار قرار الإحالة ."}, {"number": "48", "chapter": "الفصل الثاني الاختصاصات", "text": "مع مراعاة ما هو منصوص عليه بالنسبة إلى المحكمة الإدارية العليا يعمل أمامها بالقواعد والإجراءات والمواعيد المنصوص عليها فى الفصل الثالث – أولا – من الباب الأول من هذا القانون . رابعاً : أحكام عامة"}, {"number": "49", "chapter": "الفصل الثاني الاختصاصات", "text": "لايترتب على رفع الطلب إلى المحكمة وقف تنفيذ القرار المطلوب إلغاؤه على أنه يجوز للمحكمة أن تأمر بوقف تنفيذه إذا طلب ذلك فى صحيفة الدعوى ورأت المحكمة أن نتائج التنفيذ قد يتعذر تداركها . وبالنسبة إلى القرارات التى لا يقبل طلب إلغائها قبل التظلم منها إدارياً لا يجوز طلب وقف تنفيذها ، على أنه يجوز للمحكمة بناء على طلب المتظلم أن تحكم مؤقتا باستمرار صرف مرتبه كله أو بعضه إذا كان القرار صادرا بالفصل ، فإذا حكم له بهذا الطلب ثم رفض تظلمه ولم يرفع دعوى الإلغاء فى الميعاد اعتبر الحكم كأن لم يكن واسترد منه ما قبضه ."}, {"number": "50", "chapter": "الفصل الثاني الاختصاصات", "text": "لايترتب على الطعن أمام المحكمة الإدارية العليا وقف تنفيذ الحكم المطعون فيه إلا إذا أمرت دائرة فحص الطعون بغير ذلك. كما لا يترتب على الطعن أمام محكمة القضاء الإدارى فى الأحكام الصادرة من المحاكم الإدارية وقف تنفيذها إلا إذا أمرت المحكمة بغير ذلك ."}, {"number": "51", "chapter": "الفصل الثاني الاختصاصات", "text": "يجوز الطعن فى الأحكام الصادرة من محكمة القضاء الإدارى والمحاكم الإدارية والمحاكم التأديبية بطريق التماس إعادة النظر فى المواعيد والأحوال المنصوص عليها فى قانون المرافعات المدنية والتجارية أو قانون الإجراءات الجنائية حسب الأحوال وذلك بما لا يتعارض مع طبيعة المنازعات المنظورة أمام هذه المحاكم . ولا يترتب على الطعن وقف تنفيذ الحكم إلا إذا أمرت المحكمة بغير ذلك وإذا حكم بعدم قبول الطعن أو برفضه جاز الحكم على الطاعن بغرامة لا تتجاوز ثلاثين جنيها فضلا عن التعويض إذا كان له وجه ."}, {"number": "52", "chapter": "الفصل الثاني الاختصاصات", "text": "تسرى فى شأن جميع الأحكام ، القواعد الخاصة بقوة الشئ المحكوم فيه على أن الأحكام الصادرة بالإلغاء تكون حجة على الكافة"}, {"number": "53", "chapter": "الفصل الثاني الاختصاصات", "text": "تسرى فى شأن رد مستشاري المحكمة الإدارية العليا القواعد المقررة لرد مستشارى محكمة النقض وتسرى فى شأن رد مستشارى محكمة القضاء الإدارى والمحاكم التأديبية للعاملين من مستوى الإدارة العليا القواعد المقررة لرد مستشارى محاكم الاستئناف . وتسرى فى شأن رد أعضاء المحاكم الإدارية والمحاكم التأديبية الأخرى القواعد المقررة لرد القضاة ."}, {"number": "54", "chapter": "الفصل الثاني الاختصاصات", "text": "الأحكام الصادرة بالإلغاء تكون صورتها التنفيذية مشمولة بالصيغة الآتية : \" على الوزراء ورؤساء المصالح المختصين تنفيذ هذا الحكم وإجراء مقتضاه \" أما لأحكام الأخرى فتكون صورتها التنفيذية مشمولة بالصيغة الآتية: \" على الجهة التى يناط بها التنفيذ أن تبادر إليه متى طلب منها وعلى السلطات المختصة أن تعين على إجرائه ولو باستعمال القوة متى طلب إليها ذلك \" مادة 54 مكرر : إذا تبين لإحدى دوائر المحكمة الإدارية العليا عند نظر الطعون أنه صدرت منها أو من إحدى دوائر المحكمة أحكام سابقة يخالف بعضها البعض أو رأت العدول عن مبدأ قانونى قررته أحكام سابقة صادرة من المحكمة الإدارية العليا ، تعين عليها إحالة الطعن إلى هيئة تشكلها الجمعية العامة لتلك المحكمة فى كل عام قضائى من أحد عشر مستشارا برئاسة رئيس المحكمة أو الأقدم فالأقدم من نوابه . ويجب على سكرتارية المحكمة أن تعرض ملف الدعوى خلال ثلاثة أيام من صدور قرار الإحالة على رئيس المحكمة ليعين تاريخ الجلسة التى ستنظر فيها الدعوى . ويعلن الخصوم بهذا التاريخ قبل حلوله بأربعة عشر يوماً على الأقل وتصدر الهيئة المذكورة أحكامها بأغلبية سبعة أعضاء على الأقل ."}, {"number": "55", "chapter": "الفصل الرابع الجمعيات العمومية للمحاكم", "text": "تجتمع كل من المحاكم الإدارية العليا ومحكمة القضاء الإدارى بهيئة جمعية للنظر فى المسائل المتصلة بنظامها وأمورها الداخلية وتوزيع الأعمال بين أعضائها أو بين دوائرها . وتتألف الجمعية العمومية لكل محكمة من جميع مستشاريها العاملين بها ، وتدعى إليها هيئة المفوضين ويكون لممثلها صوت معدود فى المداولة . وتدعى للانعقاد بناء على طلب رئيس المجلس أو رئيس المحكمة أو ثلاثة من أعضائها أو بناء على طلب رئيس هيئة المفوضين ولا يكون انعقادها صحيحا إلا بحضور الأغلبية المطلقة لأعضائها وتكون الرئاسة لأقدم الحاضرين . ويجوز لرئيس المجلس أن يحضر أية جمعية عمومية وفى هذه الحالة تكون له الرئاسة وتصدر القرارات بالأغلبية المطلقة لأصوات الحاضرين ، وإذا تساوت الآراء يرجح الجانب الذى منه الرئيس ."}, {"number": "56", "chapter": "الفصل الرابع الجمعيات العمومية للمحاكم", "text": "تجتمع المحاكم الإدارية بهيئة جمعية عمومية تتألف من جميع أعضائها وذلك للنظر فى المسائل المتعلقة بنظامها وأمورها الداخلية ، وتدعى للانعقاد بناء على طلب رئيس المجلس أو نائب رئيس المجلس المختص لهذه المحاكم أو رئيس هيئة المفوضين أو ثلاثة من أعضائها على الأقل ، ولا يكون انعقادها صحيحا إلا بحضور الأغلبية المطلقة لأعضائها . وتدعى إليها هيئة المفوضين ويكون لممثلها صوت معدود فى المداولة ، وتكون الرئاسة لنائب رئيس المجلس لهذه المحاكم وفى حالة غيابه لأقدم الحاضرين . ويجوز لرئيس المجلس أن يحضر أية جمعية عمومية وفى هذه الحالة تكون له الرئاسة . وتصدر القرارات بالأغلبية المطلقة لأصوات الحاضرين وإذا تساوت الآراء يرجح الجانب الذي منه الرئيس ، وتبلغ القرارات إلى رئيس المجلس ولا تكون نافذة إلا بعد تصديقه عليها بعد أخذ رأى نائب رئيس المجلس المختص لهذه المحاكم"}, {"number": "57", "chapter": "الفصل الرابع الجمعيات العمومية للمحاكم", "text": "تجتمع المحاكم التأديبية بهيئة جمعية تتألف من جميع أعضائها للنظر فى المسائل المتعلقة بنظامها وأمورها الداخلية وتوزيع الأعمال بين دوائرها . وتعقد الجمعية بناء على طلب رئيس المجلس أو نائب رئيس المجلس للمحاكم التأديبية أو ثلاثة من أعضائها على الأقل . وتسرى أحكام المادة السابقة فيما يتعلق بصحة انعقد الجمعية العمومية ورئاستها والقرارات التى تصدرها ."}, {"number": "58", "chapter": "الباب الثاني قسما الفتوى والتشريع الفصل الأول قسم الفتوى", "text": "يتكون قسم الفتوى من إدارات مختصة لرياسة الجمهورية ورياسة مجلس الوزراء والوزارات والهيئات العامة ، ويرأس كل إدارة منها مستشار أو مستشار مساعد ، ويعين عدد الإدارات وتحدد دوائر اختصاصها بقرار من الجمعية العمومية للمجلس . وتختص الإدارات المذكورة بإبداء الرأى فى المسائل التى يطلب الرأى فيها من الجهات المبينة فى الفقرة الأولى وبفحص التظلمات الإدارية . ولايجوز لأية وزارة أو هيئة عامة أو مصلحة من مصالح الدولة أن تبرم أو تقبل أو تجيز أى عقد أو صلح أو تحكيم أو تنفيذ قرار محكمين فى مادة تزيد قيمتها على خمسة آلاف جنيه بغير استفتاء الإدارة المختصة"}, {"number": "59", "chapter": "الباب الثاني قسما الفتوى والتشريع الفصل الأول قسم الفتوى", "text": "يجوز أن يندب برياسة الجمهورية وبرياسة مجلس الوزراء وبالوزارات وبالمحافظات والهيئات العامة بناء على طلب رئيس الجمهورية أو رئيس مجلس الوزراء أو الوزراء أو المحافظين أو رؤساء تلك الهيئات مستشارون مساعدون أو نواب للعمل كمفوضين لمجلس الدولة للاستعانة بهم فى دراسة الشئون القانونية والتظلمات الإدارية ومتابعة ما يهم رياسة الجمهورية ورياسة مجلس الوزراء والوزارات والمحافظات والهيئات العامة لدى المجلس أو ما للمجلس لديها من مسائل تدخل فى اختصاصه طبقا للقوانين واللوائح . ويعتبر المفوض ملحقا بإدارة الفتوى المختصة بشئون الجهة التى يعمل فيها . وتبين اللائحة الداخلية النظام الذي يسير عليه هؤلاء المفوضون فى أعمالهم ."}, {"number": "60", "chapter": "الباب الثاني قسما الفتوى والتشريع الفصل الأول قسم الفتوى", "text": "يجتمع رؤساء الإدارات ذات الاختصاصات المتجانسة بهيئة لجان يرأسها نائب رئيس المجلس المختص وتبين كيفية تشكيلها وتحديد دوائر اختصاصها فى اللائحة الداخلية . كما يجوز بقرار من الجمعية العمومية للمجلس إنشاء لجنة أو أكثر تتخصص فى نوع معين من المسائل يمتد اختصاصها إلى جميع إدارات الفتوى ويتضمن قرار الجمعية طريقة تشكيلها . ويجوز أن يحضر اجتماعات اللجنة مستشارين مساعدون ونواب ومندوبون من الإدارات المختصة وأن يشتركوا فى مداولاتها ولا يكون للنواب أو للمندوبين صوت معدود فى المداولات ."}, {"number": "61", "chapter": "الباب الثاني قسما الفتوى والتشريع الفصل الأول قسم الفتوى", "text": "لرئيس إدارة الفتوى أن يحيل إلى اللجنة المختصة ما يرى إحالته إليها لأهمية من المسائل التى ترد إليه لإبداء الرأى فيها ، وعليه أن يحيل إلى اللجنة المسائل الآتية : (أ) كل التزام موضوعه استغلال مورد من الموارد الثروة الطبيعية فى البلاد أو مصلحة من مصالح الجمهور العامة . (ب) عقود التوريد والأشغال العامة ، وعلى وجه العموم كل عقد يرتب حقوقا أو التزامات مالية للدولة وغيرها من الأشخاص الاعتبارية العامة أو عليها إذا زادت قيمته على خمسين ألف جنيه . (ج) الترخيص فى تأسيس الشركات التى ينص القانون على أن يكون إنشاؤها بقرار من رئيس الجمهورية . (د) المسائل التى يرى فيها أحد المستشارين رأيا يخالف فتوى صدرت من أحد الإدارات قسم الفتوى أو لجانه . ويجوز لرئيس المجلس أن يعهد إلى إدارة الفتوى التى يكون مقرها خارج القاهرة بمباشرة اختصاص اللجنة ."}, {"number": "62", "chapter": "الفصل الثاني قسم التشريع", "text": "يشكل قسم التشريع من أحد نواب رئيس المجلس ومن عدد كاف من المستشارين والمستشارين المساعدين ويلحق به نواب ومندوبون . وعند انعقاد القسم يتولى رياسته نائب رئيس المجلس وفى حالة غيابه أقدم مستشارى القسم ، وعليه أن يدعو رئيس إدارة الفتوى المختصة عند نظر التشريعات الخاصة بإدارته للاشتراك فى المداولات ويكون له صوت معدود فيها ، وتصدر القرارات بأغلبية أصوات الحاضرين ."}, {"number": "63", "chapter": "الفصل الثاني قسم التشريع", "text": "على كل وزارة أو مصلحة قبل استصدار أى قانون أو قرار من رئيس الجمهورية ذي صفة تشريعية أو لائحة أن تعرض المشروع المقترح على قسم التشريع لمراجعة صياغته ، ويجوز لها أن تعهد إليه بإعداد هذه التشريعات ."}, {"number": "64", "chapter": "الفصل الثاني قسم التشريع", "text": "تقوم بمراجعة صياغة التشريعات التى يرى رئيس مجلس الوزراء أو أحد الوزراء أو رئيس المجلس الدولة نظرها على وجه الاستعجال لجنة تشكل من رئيس قسم التشريع أو من يقوم مقامه وأحد مستشارى القسم يندبه رئيس القسم ورئيس إدارة الفتوى المختصة ."}, {"number": "65", "chapter": "الفصل الثالث الجمعية العمومية لقسمي الفتوى والتشريع", "text": "تشكل الجمعية العمومية لقسمي الفتوى والتشريع برياسة نائب لرئيس المجلس وعضوية نواب رئيس المجلس بقسمي الفتوى والتشريع ومستشاري قسم التشريع ورؤساء إدارات الفتوى ."}, {"number": "66", "chapter": "الفصل الثالث الجمعية العمومية لقسمي الفتوى والتشريع", "text": "تختص الجمعية العمومية لقسم الفتوى والتشريع بإبداء الرأى فى المسائل والموضوعات الآتية : (أ) المسائل الدولية والدستورية والتشريعية وغيرها من المسائل القانونية التى تحال إليها بسبب أهميتها من رئيس الجمهورية أو من رئيس الهيئة التشريعية أو من رئيس مجلس الوزراء أو من أحد الوزراء أو من رئيس مجلس الدولة . (ب) المسائل التى ترى فيها إحدى لجان قسم الفتوى رأيا يخالف فتوى صدرت من لجنة أخرى أو من الجمعية العمومية لقسمي الفتوى والتشريع . (ج) المسائل التى ترى فيها إحدى لجان قسم الفتوى إحالتها إليها لأهميتها . (د) المنازعات التى تنشأ بين الوزارات أو بين المصالح العامة أو بين الهيئات العامة أو بين المؤسسات العامة أو بين الهيئات المحلية أو بين هذه الجهات وبعضها البعض . ويكون رأى الجمعية العمومية لقسمي الفتوى والتشريع فى هذه المنازعات ملزما للجانبين . ويجوز لمن طلب إبداء الرأى فى المسائل المنصوص عليها فى الفقرة (أ) أن يحضر بنفسه جلسات الجمعية عند النظر فى هذه المسائل ، كما يجوز له أن يندب من يراه من ذوى الخبرة كمستشارين غير عاديين وتكون لهم – وإن تعددوا – صوت واحد فى المداولات . كما تختص الجمعية العمومية بمراجعة مشروعات القوانين وقرارات رئيس الجمهورية ذات الصفة التشريعية واللوائح التى يرى قسم التشريع إحالتها إليها لأهميتها ."}, {"number": "67", "chapter": "الفصل الثالث الجمعية العمومية لقسمي الفتوى والتشريع", "text": "تبين اللائحة الداخلية للمجلس نظام العمل فى إدارات قسم الفتوى ولجانه وقسم التشريع ، كما تبين اختصاص كل عضو من أعضاء إدارات الفتوى والمسائل التى يبت فيها كل منهم بصفة نهائية ، ويجوز عند الاقتضاء أن ينوب المستشارين المساعدون عن المستشارين فى اختصاصاتهم ."}, {"number": "68", "chapter": "الباب الثالث أحكام عامة", "text": "تشكل الجمعية العمومية لمجلس الدولة من جميع المستشارين ويتولى رياستها رئيس المجلس وعند غيابه أقدم الحاضرين من نواب الرئيس ثم من المستشارين. وتدعى الجمعية للانعقاد بناء على طلب الرئيس أو خمسة من أعضائها ولا يكون انعقادها صحيحا إلا بحضور الأغلبية المطلقة لأعضائها وتختص الجمعية العمومية عدا ما هو مبين فى هذا القانون بإصدار اللائحة الداخلية للمجلس . مادة 68 مكرر : ينشأ بمجلس الدولة مجلس خاص للشئون الإدارية برئاسة رئيس مجلس الدولة وعضوية أقدم ستة من نواب رئيس المجلس وعند غياب أحدهم أو وجود مانع لديه يحل محله الأقدم فالأقدم من نواب رئيس المجلس . ويختص هذا المجلس بالنظر فى تعيين أعضاء مجلس الدولة وتحديد أقدميتهم وترقياتهم ونقلهم وندبهم خارج المجلس وإعارتهم التظلمات المتصلة بذلك وكذلك سائر شئونهم على الوجه المبين فى هذا القانون . ويجب أخذ رأيه فى مشروعات القوانين المتصلة بمجلس الدولة . ويجتمع هذا المجلس بدعوة من رئيسه وتكون جميع مداولاته سرية وتصدر القرارات بأغلبية أعضائه ."}, {"number": "69", "chapter": "الباب الثالث أحكام عامة", "text": "يقدم رئيس مجلس الدولة كل سنة كلما رأى ضرورة لذلك تقريرا إلى رئيس مجلس الوزراء متضمنا ما أظهرته الأحكام أو البحوث من نقض فى التشريع القائم أو غموض فيه أو حالات إساءة استعمال السلطة من أية جهة من جهات الإدارة أو مجاوزة تلك الجهات لسلطتها ."}, {"number": "70", "chapter": "الباب الثالث أحكام عامة", "text": "ينوب رئيس مجلس الدولة عن المجلس فى صلاته بالغير ، ويرأس الجمعية العمومية للمجلس ، ويجوز له أن يحضر جلسات الجمعية العمومية لقسمى الفتوى والتشريع ولجانه وجلسات قسم التشريع وتكون له الرئاسة فى هذه الحالات . ويشرف رئيس المجلس على أعمال أقسام المجلس المختلفة وتوزيع العمل بينها كما يشرف على الأعمال الإدارية وعلى الأمانة العامة للمجلس وعند غياب الرئيس أو خلو منصبه يحل محله فى اختصاصاته الأقدم فالأقدم من نواب الرئيس ."}, {"number": "71", "chapter": "الباب الثالث أحكام عامة", "text": "يعاون رئيس المجلس فى تنفيذ اختصاصاته المبينة فى المادة السابقة أمين عام من درجة مستشار مساعد على الأقل يندب بقرار من رئيس المجلس ."}, {"number": "72", "chapter": "الباب الثالث أحكام عامة", "text": "يشكل بالأمانة العامة لمجلس الدولة مكتب فني برياسة الأمين العام ، ويندب أعضاؤه بقرار من رئيس المجلس من بين المستشارين المساعدين والنواب والمندوبين ، ويلحق به عدد كاف من الموظفين الإداريين والكتابيين . ويختص المكتب الفني بإعداد البحوث التى يطلب إليها رئيس المجلس القيام بها ، كما يشرف على أعمال الترجمة والمكتبة وإصدار مجلة المجلس ومجموعات الأحكام والفتاوى وتبويبها وتنسيقها . الباب الرابع فى نظام أعضاء مجلس الدولة الفصل الأول فى تعيين والترقية وتحديد الأقدمية"}, {"number": "73", "chapter": "الباب الثالث أحكام عامة", "text": "يشترط فيمن يعين عضوا فى مجلس الدولة : أن يكون مصريا متمتعا بالأهلية المدنية الكاملة . أن يكون حاصلا على درجة الليسانس من إحدى كليات الحقوق بجمهورية مصر العربية أو على شهادة أجنبية معادلة لها وأن ينجح فى الحالة الأخيرة فى امتحان المعادلة طبقا للقوانين واللوائح الخاصة بذلك . أن يكون محمود السيرة حسن السمعة . ألا يكون قد حكم عليه من المحاكم أو مجالس التأديب لأمر مخل بالشرف ولو كان قد رد إليه اعتباره . أن يكون حاصلا على دبلومتين من دبلومات الدراسات العليا أحدهما فى العلوم الإدارية أو القانون العام إذا كان التعيين فى وظيفة مندوب . ألا يكون متزوجا بأجنبية ومع ذلك يجوز بإذن من رئيس الجمهورية الإعفاء من هذا الشرط إذا كان متزوجا بمن تنتمى بجنسيتها إلى إحدى البلاد العربية . ألا تقل سن من يعين مستشارا بالمحاكم عن ثمان وثلاثين سنة ولا تقل سن من يعين عضوا بالمحاكم الإدارية والتأديبية عن ثلاثين سنة ولا تقل سن من يعين مندوبا مساعدا عن تسع عشر سنة ."}, {"number": "74", "chapter": "الباب الثالث أحكام عامة", "text": "مع مراعاة الشروط المنصوص عليها فى المادة السابقة يكون التعيين فى وظائف مجلس الدولة بطريق الترقية من الوظائف التى تسبقها مباشرة ، على أنه يجوز أن يعين رأسا من غير أعضاء المجلس فى الوظائف المنصوص عليها فى المواد التالية وبالشروط المقررة بها وذلك فى حدود ربع عدد الدرجات الخالية فى كل وظيفة خلال سنة مالية كاملة . ولا يدخل فى هذه النسبة وظائف المندوبين والوظائف التى تملاء بالتبادل بين شاغليها ومن يحل محلهم من خارج المجلس وكذلك الوظائف المنشأة ."}, {"number": "75", "chapter": "الباب الثالث أحكام عامة", "text": "يعتبر المندوب المساعد معينا فى وظيفة مندوب من أول يناير التالى لحصوله على الدبلومتين المنصوص عليهما فى البند (5) من المادة 73 متى كانت التقارير المقدمة عنه مرضية . ويجوز أن يعين مباشرة فى وظيفة مندوب الحاصلون على هذين الدبلومتين من الفئات الآتية : (أ) المندوبون السابقون بمجلس الدولة . (ب) من يشغلون وظيفة وكيل النائب العام أو وكيل النيابة الإدارية أو محام بإدارة قضايا الحكومة . (ج) المعيدون فى كلية الحقوق أو فى مادة القانون بجامعات جمهورية مصر العربية متى أمضى المعيد ثلاث سنوات فى عمله وكان راتبه يدخل فى حدود مرتب مندوب . (د) المشتغلون بعمل يعتبر بقرار من المجلس الأعلى للهيئات القضائية نظيرا للعمل القضائى متى أمضى كل منهم ثلاث سنوات فى عمله . (هـ) المحامون المشتغلون أمام المحاكم الابتدائية مدة سنة على الأقل ."}, {"number": "76", "chapter": "الباب الثالث أحكام عامة", "text": "يجوز أن يعين فى وظيفة نائب من الفئة (ب) : (أ) النواب السابقون بمجلس الدولة . (ب) قضاة المحاكم الابتدائية ووكلاء النائب العام من الفئة الممتازة ووكلاء النيابة الإدارية من الفئة الممتازة والنواب بإدارة قضايا الحكومة (ج) أعضاء هيئة التدريس بكليات الحقوق وأعضاء هيئة تدريس القانون بجامعات جمهورية مصر العربية والمشتغلون بعمل يعتبر بقرار من المجلس الأعلى للهيئات القضائية نظيرا للعمل القضائي متى أمضوا جميعا تسع سنوات متوالية فى العمل القانونى وكانوا فى درجات مماثلة لدرجة نائب من الفئة (ب) أو يتقاضون مرتبا يدخل حدود هذه الدرجة . (د) المحامون الذين اشتغلوا أمام محاكم الاستئناف أربع سنوات متوالية بشرط أن يكونوا قد مارسوا فعلا لمدة تسع سنوات المحاماة أو أى عمل يعتبر بقرار يصدر من المجلس الأعلى للهيئات القضائية نظيرا للعمل القضائى ."}, {"number": "77", "chapter": "الباب الثالث أحكام عامة", "text": "يجوز أن يعين فى وظيفة نائب من الفئة (أ) : (أ) النواب السابقون بمجلس الدولة الذين شغلوا هذه الدرجة خمس سنوات على الأقل . (ب) قضاة المحاكم الابتدائية ووكلاء النيابة الإدارية من الفئة الممتازة والنواب بإدارة قضايا الحكومة الشاغلون لوظائف معادلة بتلك الجهات . (ج) الأساتذة المساعدون بكليات الحقوق وأساتذة القانون والمساعدون بجامعات جمهورية مصر العربية والمشتغلون بعمل يعتبر بقرار يصدر من المجلس الأعلى للهيئات القضائية نظيرا للعمل القضائي متى أمضوا أربعة عشر سنة متولية فى العمل القانونى وكانوا فى درجات مماثلة لدرجات نائب من الفئة (أ) أو يتقاضون مرتبا يدخل فى حدود هذه الدرجة . (د) المحامون الذين اشتغلوا أمام محاكم الاستئناف مدة تسع سنوات متتالية بشرط أن يكونوا قد مارسوا المحاماة فعلا أو أى عمل يعتبر بقرار من المجلس الأعلى للهيئات القضائية نظيرا للعمل القضائي مدة أربع عشرة سنة ."}, {"number": "78", "chapter": "الباب الثالث أحكام عامة", "text": "يجوز أن يعين فى وظيفة مستشار مساعد من الفئة (ب) : أ) المستشارين المساعدون السابقون بمجلس الدولة . ب) رؤساء المحاكم الابتدائية والمستشارون المساعدون بإدارة قضايا الحكومة ورؤساء النيابة الإدارية . ج) أساتذة كليات الحقوق وأساتذة القانون بجامعات جمهورية مصر العربية أو الأساتذة المساعدون بهذه الجامعات الذين أمضوا فى وظيفة أستاذ مساعد مدة لا تقل عن خمس سنوات . د) المحامون الذين اشتغلوا أمام محاكم الاستئناف مدة اثنتي عشرة سنة متتالية بشرط أن يكونوا قد مارسوا المحاماة فعلا أو أى عمل يعتبر بقرار من المجلس الأعلى للهيئات القضائية نظيرا للعمل القضائي مدة سبع عشرة سنة . هـ) المشتغلون بعمل يعتبر بقرار من المجلس الأعلى للهيئات القضائية نظيرا للعمل القضائي ممن أمضوا سبعة عشرة ستة متوالية فى العمل القانوني وكانوا فى درجات مماثلة لدرجة مستشار مساعد من الفئة (ب) أو يتقاضون مرتبا يدخل فى حدود هذه الدرجة ."}, {"number": "79", "chapter": "الباب الثالث أحكام عامة", "text": "يجوز أن يعين فى وظيفة مستشار مساعد من الفئة (أ) : (أ) المستشارون المساعدون السابقون بمجلس الدولة الذين أمضوا فى هذه الدرجة ثلاث سنوات على الأقل . (ب) الرؤساء بالمحاكم الابتدائية ورؤساء النيابة العامة والنيابة الإدارية والمستشارون المساعدون بإدارة قضايا الحكومة الشاغلون لوظائف معادلة بتلك الجهات . (ج) أساتذة كليات الحقوق وأساتذة القانون بجامعات جمهورية مصر العربية الذين لأمضوا فى وظيفة أستاذ مدة لا تقل عن سنتين . (د) المشتغلون بعمل يعتبر بقرار من المجلس الأعلى للهيئات القضائية نظيرا للعمل القضائي مدة عشرين سنة وكانوا فى درجات مماثلة لدرجة مستشار مساعد من الفئة (أ) أو يتقاضون مرتبا يدخل فى حدود هذه الدرجة . (هـ) المحامون الذين اشتغلوا أمام محاكم الاستئناف خمس عشرة سنة متوالية بشرط أن يكونوا قد مارسوا المحاماة فعلا أو أى عمل يعتبر بقرار من المجلس الأعلى للهيئات القضائية نظيرا للعمل القضائي مدة عشرين سنة ."}, {"number": "80", "chapter": "الباب الثالث أحكام عامة", "text": "يجوز أن يعين فى وظيفة مستشار : (أ) المستشارون السابقون بمجلس الدولة . (ب) المستشارون بمحاكم الاستئناف والمحامون العامون بالنيابة العامة والوكلاء العامون بالنيابة الإدارية والمستشارون بإدارة قضايا الحكومة . (ج) أساتذة كليات الحقوق وأساتذة القانون بجامعات جمهورية مصر العربية الذين أمضوا فى وظيفة أستاذ مدة لا تقل عن ثلاث سنوات . (د) المحامون الذين اشتغلوا أمام محكمة النقض خمس سنوات متوالية ."}, {"number": "81", "chapter": "الباب الثالث أحكام عامة", "text": "استثناء من أحكام المواد 75 ، 76 ، 77 ، 78 ، 79 يجوز أن يعين رجال القضاء والنيابة العامة والنيابة الإدارية وأعضاء إدارة قضايا الحكومة والمشتغلون بالتدريس فى كليات الحقوق أو بتدريس مادة القانون فى جامعات جمهورية مصر العربية فى وظائف أعضاء مجلس الدولة التى تلى مباشرة درجات وظائفهم فى جهاتهم الأصلية على ألا يترتب على ذلك أن يسبقوا زملائهم بمجلس الدولة ."}, {"number": "82", "chapter": "الباب الثالث أحكام عامة", "text": "يشترط فيمن يلحق مستشارا بالمحكمة الإدارية العليا أن يكون قد شغل وظيفة مستشار بمجلس الدولة مدة ثلاث سنوات على الأقل ."}, {"number": "83", "chapter": "الباب الثالث أحكام عامة", "text": "يعين رئيس مجلس الدولة بقرار من رئيس الجمهورية من بين نواب رئيس المجلس بعد أخذ رأى جمعية عمومية خاصة تشكل من رئيس مجلس الدولة ونوابه ووكلائه والمستشارين الذين شغلوا وظيفة مستشار لمدة سنتين . ويعين نواب رئيس المجلس ووكلائه بقرار من رئيس الجمهورية بعد موافقة الجمعية العمومية للمجلس . ويعين باقي الأعضاء والمندوبون المساعدون بقرار من رئيس الجمهورية بعد موافقة المجلس الخاص للشئون الإدارية . ويعتبر تاريخ التعيين أو الترقية من وقت موافقة الجمعية العمومية أو المجلس المشار إليه حسب الأحوال ."}, {"number": "84", "chapter": "الباب الثالث أحكام عامة", "text": "يكون اختيار النواب من الفئة (ب) بطريق الترقية من بين المندوبين على أساس الأقدمية ومن واقع أعمالهم وتقارير التفتيش عنهم . وتكون ترقية النواب من الفئتين (ب و أ) والمستشارين المساعدين من الفئتين (ب و أ) على أساس الأقدمية مع الأهلية . ويجوز ترقيتهم للكفاية الممتازة ولو لم يحل دورهم فى الترقية متى أمضوا فى وظائفهم سنتين على الأقل ، وبشرط ألا تزيد نسبة من يرقى منهم لهذا السبب على ربع عدد الوظائف الخالية فى كل درجة خلال سنة مالية كاملة ، ويكون اختيارهم بترتيب الأقدمية فيما بينهم . ويعتبر من ذوى الكفاية الممتازة النواب والمستشارون المساعدون الحاصلون – فى آخر تقريرين لكفايتهم فى تقارير التفتيش الفني – على درجة كفء وبشرط ألا تقل تقديراتهم السابقة جميعها عن درجة فوق المتوسط . وفيما عدا ذلك يجرى الاختيار فى الوظائف الأخرى على أساس درجة الأهلية ، وعند التساوي تراعى الأقدمية ."}, {"number": "85", "chapter": "الباب الثالث أحكام عامة", "text": "تعين الأقدمية وفقاً لتاريخ القرار الصادر بالتعيين أو الترقية وإذا عين اثنان أو أكثر فى وقت واحد وفى الدرجة عينها أو رقوا إليها حسبت أقدميته وفقاً لترتيب تعيينهم أو ترقيتهم . وتعتبر أقدمية أعضاء المجلس الذين يعادون إلى مناصبهم من تاريخ تعيينهم أول مرة . وتحدد أقدمية من يعينون من خارج المجلس فى قرار التعيين وذلك بعد موافقة المجلس الخاص للشئون الإدارية ويجوز أن تحدد أقدمية رجال القضاء والنيابة العامة والنيابة الإدارية وإدارة قضايا الحكومة وغيرها ممن يعينون من خارج السلك القضائى عند تعيينهم فى وظائف مجلس الدولة المماثلة لدرجاتهم من تاريخ تعيينهم فى هذه الدرجات وبشرط ألا يترتب على ذلك أن يسبقوا زملائهم فى المجلس . وتحدد أقدمية المحامين عند تعيينهم فى وظائف مجلس الدولة من تاريخ استيفائهم لشروط الصلاحية للوظائف المعينين فيها على ألا يترتب على ذلك أن يسبقوا زملائهم فى المجلس ."}, {"number": "86", "chapter": "الباب الثالث أحكام عامة", "text": "يؤدى أعضاء مجلس الدولة والمندوبون المساعدون قبل اشتغالهم بوظائفهم اليمين الآتية : أقسم بالله العظيم أن أحكم بالعدل وأن أؤدى أعمال وظيفتى بالذمة والصدق وأن أخدم القوانين . ويكون أداء رئيس المجلس اليمين أمام رئيس الجمهورية . ويكون أداء اليمين بالنسبة لنواب رئيس المجلس والمستشارين والمساعدين أمام المحكمة الإدارية العليا ، أما باقى الأعضاء والمندوبون المساعدون فيؤدون اليمين أمام رئيس مجلس الدولة ."}, {"number": "87", "chapter": "الفصل الثاني فى النقل والندب والإعارة", "text": "يتم إلحاق أعضاء مجلس الدولة بأقسامه المختلفة وندبهم من قسم إلى آخر أو بين فروع القسم الواحد بقرار من رئيس مجلس الدولة . ومع ذلك يجوز ندب المستشار بمحكمة القضاء الإدارى من دائرة إلى أخرى عند الضرورة بقرار من نائب رئيس المحكمة . كما يجوز ندب رؤساء وأعضاء المحاكم الإدارية والتأديبية من محكمة إلى أخرى عند الضرورة بقرار من نائب رئيس المجلس للمحاكم الإدارية أو التأديبية . ويجوز أيضاً ندب أعضاء هيئة مفوضى الدولة من محكمة إلى أخرى عند الضرورة بقرار من رئيس الهيئة ."}, {"number": "88", "chapter": "الفصل الثاني فى النقل والندب والإعارة", "text": "يجوز ندب أعضاء مجلس الدولة كل الوقت أو فى غير أوقات العمل الرسمية أو إعارتهم للقيام بإعمال قضائية أو قانونية لوزارات الحكومة ومصالحها أو الهيئات العامة أو المؤسسات العامة وذلك بقرار من رئيس مجلس الدولة بعد موافقة المجلس الخاص للشئون الإدارية على أن يتولى المجلس المذكور وحده تحديد المكافأة التى يستحقها العضو المنتدب أو المعار عن هذه الأعمال . أما بالنسبة إلى الهيئات أو اللجان التى يرأسها أو يشترك فى عضويتها بحكم القانون أحد أعضاء مجلس الدولة فيكون الندب لها بقرار من رئيس المجلس . كما تجوز إعارة أعضاء مجلس الدولة للقيام بأعمال قضائية أو قانونية للحكومات الأجنبية أو للهيئات الدولية وذلك بقرار من رئيس الجمهورية بعد موافقة المجلس الخاص للشئون الإدارية . ولا يجوز أن يترتب على الندب أو الإعارة الإخلال بحسن سير العمل ."}, {"number": "89", "chapter": "الفصل الثاني فى النقل والندب والإعارة", "text": "لايجوز أن تزيد مدة إعارة عضو مجلس الدولة إلى الخارج على أربع سنوات متصلة ، وتعتبر المدة المتصلة إذا تتابعت أيامها أو فصل بينها فاصل زمنى يقل عن خمس سنوات . ومع ذلك يجوز أن تزيد المدة على هذا القدر إذا اقتضت ذلك مصلحة قومية يقدرها رئيس الجمهورية ."}, {"number": "90", "chapter": "الفصل الثاني فى النقل والندب والإعارة", "text": "يجوز شغل وظيفة المعار بدرجتها إذا كانت مدة الإعارة لا تقل عن سنة فإذا عاد المعار إلى عمله بمجلس الدولة قبل نهاية هذه المدة يشغل الوظيفة الخالية من درجته أو يشغل درجته الأصلية بصفة شخصية على أن تسوى حالته على أول وظيفة تخلو من درجته ."}, {"number": "91", "chapter": "الفصل الثالث فى عدم قابلية أعضاء مجلس الدولة للعزل", "text": "أعضاء مجلس الدولة من درجة مندوب فما فوقها غير قابلين للعزل ويسرى بالنسبة لهؤلاء جميع الضمانات التى يتمتع بها رجال القضاء وتكون الهيئة المشكل منها مجلس التأديب هى الجهة المختصة فى كل ما يتصل بها بهذا الشأن . ومع ذلك إذا اتضح أن أحدهم فقد الثقة والاعتبار الذين تتطلبهما الوظيفة أو فقد أسباب الصلاحية لأدائها لغير الأسباب الصحية أحيل إلى المعاش أو نقل إلى وظيفة معادلة غير قضائية بقرار من رئيس الجمهورية بعد موافقة مجلس التأديب."}, {"number": "92", "chapter": "الفصل الثالث فى عدم قابلية أعضاء مجلس الدولة للعزل", "text": "يقدم طلب النظر فى الإحالة إلى المعاش أو النقل إلى وظيفة غير قضائية من رئيس مجلس الدولة ، وعلى مجلس التأديب أو الهيئة المشكل منها حسب الأحوال أن يدعو العضو للحضور أمامه لسماع أقواله . وللمجلس أن يقرر اعتبار العضو فى أجازه حتمية بمرتب كامل إلى أن يصدر قرار فى الطلب بقبوله أو رفضه ."}, {"number": "93", "chapter": "الفصل الثالث فى عدم قابلية أعضاء مجلس الدولة للعزل", "text": "يعرض رئيس مجلس الدولة على الهيئة المشكل منها مجلس التأديب أمر المستشارين المساعدين والنواب الذين يحصلون على تقريرين متتاليين بدرجة أقل من المتوسط ، وتقوم الهيئة بفحص حالتهم وسماع أقوالهم فإذا تبين لها صحة التقارير أو ضروراتها نهائية قررت إحالتهم إلى المعاش أو نقلهم إلى وظيفة أخرى غير قضائية . ويصدر بالإحالة إلى المعاش أو بالنقل قرار من رئيس الجمهورية بناء على طلب من رئيس مجلس الدولة . ويعتبر تاريخ الإحالة إلى المعاش من يوم النشر قرار رئيس الجمهورية بالجريدة الرسمية ."}, {"number": "94", "chapter": "الفصل الرابع فى واجبات الأعضاء", "text": "لايجوز لعضو مجلس الدولة القيام بأي عمل تجارى كما لا يجوز له القيام بأي عمل لا يتفق واستقلال القضاء وكرامته . ويجوز للمجلس الأعلى للهيئات القضائية أن يقرر منع عضو مجلس الدولة من مباشرة أى عمل يرى أن القيام به يتعارض مع واجبات الوظيفة وحسن أدائها ."}, {"number": "95", "chapter": "الفصل الرابع فى واجبات الأعضاء", "text": "يحظر على أعضاء مجلس الدولة الاشتغال بالعمل السياسي . ولايجوز لهم الترشيح لانتخابات مجلس الشعب أو الهيئات المحلية إلا بعد تقديم استقالتهم وتعتبر الاستقالة فى هذه الحالة مقبولة بمجرد تقديمها . مادة 95 مكرر : يسوى المعاش المستحق لعضو مجلس الدولة المستقيل طبقاً لحكم المادة السابقة الذى يرشح نفسه لعضوية مجلس الشعب وفقاً للقواعد الآتية : (أ) من بلغت مدة خدمته المحسوبة فى المعاش سبعا وعشرين سنة فأكثر ، يحصل على معاش يساوى أربع أخماس آخر مربوط الوظيفة التى كان يشغلها أو أربعة أخماس المرتب الأصلي الذي كان يتقاضاه أيهما أصلح له . (ب) من بلغت مدة خدمته المحسوبة فى المعاش عشرين سنة وتقل عن سبع وعشرين تضاف خمس سنوات افتراضية إلى مدة خدمته بشرط ألا يجاوز سنه افترضا ستين سنة ، وبحيث لا يقل المعاش الذى يحصل عليه عن ثلاثة أخماس آخر مربوط الوظيفة التى كان يشغلها أو ثلاثة أخماس المرتب الأصلي الذي كان يتقاضاه أيهما أصلح له . (ج) من بلغت مدة خدمته المحسوبة فى المعاش خمس عشرة سنة وتقل عن عشرين ، تضاف خمس سنوات افتراضية إلى مدة خدمته بشرط ألا يجاوز شنه افتراضا ستين سنة ، وبحيث لا يقل المعاش الذى يحصل عليه عن نصف آخر مربوط الوظيفة التى كان يشغلها أو نصف المرتب الأصلي الذي كان يتقاضاه أيهما أصلح له . وإذا لم ينجح العضو المستقيل فى الانتخابات وحصل على عشر عدد الأصوات الصحيحة التى أعطيت على الأقل ، صرف له الفرق بين المرتب الأصلى الذى كان يتقاضاه عند تقديم الاستقالة وبين المعاش الذي استحقه وفقاً للقواعد السابقة وذلك لمدة ثلاث سنوات من تاريخ الاستقالة أو بلوغه سن الإحالة إلى المعاش أو الوفاة أيهما أقرب . وتسرى أحكام البنود ( أ , ب ، ج ) على عضو مجلس الدولة الذى يعين عضوا فى مجلس الشعب ."}, {"number": "96", "chapter": "الفصل الرابع فى واجبات الأعضاء", "text": "لايجوز لأعضاء مجلس الدولة إفشاء سر المداولات ."}, {"number": "97", "chapter": "الفصل الرابع فى واجبات الأعضاء", "text": "لايجوز لعضو مجلس لدولة أن ينقطع عن عمله دون أن يرخص له فى كتابة إلا إذا كان انقطاعه لسبب مفاجئ فإذا زادت مدة الانقطاع عن سبعة أيام فى السنة حسبت المدة الزائدة من أجازته السنوية ."}, {"number": "98", "chapter": "الفصل الرابع فى واجبات الأعضاء", "text": "يعتبر عضو مجلس الدولة مستقيلا إذا أنقطع عن عمله مدة ثلاثين يوما متصلة بدون إذن ولو كان ذلك بعد انتهاء أجازته أو أعارته أو ندبه لغير عمله . ومع ذلك إذا عاد العضو وقدم أسبابا تبرر انقطاعه عرضها رئيس مجلس الدولة على المجلس الخاص للشئون الإدارية فإن تبين له جديتها اعتبر غير مستقيل وفى هذه الحالة تحسب مدة الغياب أجازه من نوع الإجازة السابقة أو أجازه اعتيادية بحسب الأحوال ."}, {"number": "99", "chapter": "الفصل الخامس فى التفتيش على أعضاء مجلس الدولة", "text": "تشكل بمجلس الدولة إدارة للتفتيش الفنى على أعمال المستشارين المساعدين والنواب والمندوبين والمساعدين برئاسة أحد نواب رئيس المجلس وعضوية عدد كاف من المستشارين والمستشارين المساعدين . ويكون تقدير الكفاية بإحدى الدرجات الآتية : كفء – فوق متوسط – متوسط – أقل من متوسط . ويجب إجراء التفتيش مرة على الأقل كل سنتين ويجب إيداع تقرير التفتيش خلال شهرين على الأقل من تاريخ انتهاء التفتيش . كما يجب أن يحاط أعضاء مجلس الدولة علما بكل ما يودع بملفات خدمتهم من تقارير أو ملاحظات أو أوراق . وتنظم اللائحة الداخلية لمجلس الدولة طريقة العمل بإدارة التفتيش وإجراءاته وتبين الضمانات الواجب توفيرها لأعضاء المجلس الخاضعين للتفتيش ."}, {"number": "100", "chapter": "الفصل الخامس فى التفتيش على أعضاء مجلس الدولة", "text": "يخطر رئيس مجلس الدولة من تقدر كفايته بدرجة متوسط أو أقل من المتوسط من الأعضاء وذلك بمجرد انتهاء إدارة التفتيش الفنى من تقدير كفايته ، ولمن أخطر الحق فى التظلم من التقدير خلال خمسة عشر يوما من تاريخ الأخطار . كما يقوم رئيس مجلس الدولة – قبل عرض مشروع حركة الترقيات – على المجلس الخاص للشئون الإدارية بثلاثين يوما على الأقل ، بإخطار أعضاء مجلس الدولة الذين حل دورهم ولم تشملهم حركة الترقيات لسبب غير متصل بتقارير الكفاية التى فصل فيها وفقا للمادة 102 أو فات ميعاد التظلم منها ، ويبين بالأخطار أسباب التخطي ، ولمن أخطر الحق فى التظلم فى الميعاد المنصوص عليه فى الفقرة السابقة . ويتم الأخطار المشار إليه فى الفقرتين السابقتين بخطاب موصى عليه مصحوب بعلم الوصول ."}, {"number": "101", "chapter": "الفصل الخامس فى التفتيش على أعضاء مجلس الدولة", "text": "يكون التظلم بعريضة تقدم إلى إدارة التفتيش الفنى ، وعلى هذه الإدارة إحالة التظلم إلى المجلس الخاص للشئون الإدارية خلال خمسة أيام من تاريخ تقديم التظلم ."}, {"number": "102", "chapter": "الفصل الخامس فى التفتيش على أعضاء مجلس الدولة", "text": "ويفصل المجلس الخاص للشئون الإدارية فى التظلم بعد الإطلاع على الأوراق وسماع أقوال المتظلم ويصدر قراره خلال خمسة عشر يوما من تاريخ إحالة الأوراق إليه وقبل إجراء حركة الترقيات . ويقوم المجلس الخاص للشئون الإدارية أيضاً عند نظر مشروع حركة الترقيات بفحص تقارير كفاية المرشحين للترقية من درجة فوق المتوسط أو كفء . ولا يجوز للمجلس الخاص بالشئون الإدارية النزول بهذا التقدير إلى درجة أدنى إلا بعد أخطار صاحب الشأن بخطاب موصى عليه مصحوب بعلم الوصول لسماع أقوله وبعد أن تبدى إدارة التفتيش الفني رأيها مسببا فى اقتراح النزول بالتقدير ويكون قرار المجلس الخاص للشئون الإدارية فى شأن تقدير الكفاية أو التظلم منه نهائيا ويخطر به صاحب الشأن بكتاب موصى عليه بعلم الوصول ."}, {"number": "103", "chapter": "الفصل الخامس فى التفتيش على أعضاء مجلس الدولة", "text": "تعرض على المجلس الأعلى للهيئات القضائية عند نظر مشروع حركة الترقيات قرارات اللجنة المشار إليها فى المادة 100 الصادرة فى التظلمات من التخطى للأسباب غير المتصلة بتقارير الكفاية طبقا لما هو مقرر فى الفقرة الثانية من المادة 100 وذلك لإعادة النظر فيها . وتكون قرارات المجلس الأعلى للهيئات القضائية نهائية ويخطر بها المتظلم بكتاب موصى عليه مصحوب بعلم الوصول ."}, {"number": "104", "chapter": "الفصل الخامس فى التفتيش على أعضاء مجلس الدولة", "text": "تختص إحدى دوائر المحكمة الإدارية العليا دون غيرها بالفصل فى الطلبات التى يقدمها رجال مجلس الدولة بإلغاء القرارات الإدارية النهائية المتعلقة بأى شأن من شئونهم وذلك عدا النقل والندب متى كان مبنى الطلب عيبا فى الشكل أو مخالفة القوانين واللوائح أو خطأ فى تطبيقها أو تأويلها أو إساءة استعمال السلطة . كما تختص الدائرة المذكورة دون غيرها بالفصل فى طلبات التعويض عن تلك القرارات . وتختص أيضا دون غيرها لا فصل فى المنازعات الخاصة والمرتبات والمعاشات والمكافآت المستحقة لرجال مجلس الدولة أو لورثتهم . ولايجوز أن يجلس للفصل فى هذه المسائل من كان عضوا فى المجلس الأعلى للهيئات القضائية إذا كان قد اشترك فى القرار الذى رفع الطلب بسببه ولا تحصل رسوم على هذا الطلب ."}, {"number": "105", "chapter": "الفصل السادس فى الإجازات", "text": "تبدأ العطلة القضائية للمحاكم كل عام من أول يوليه وتنتهى فى آخر سبتمبر ."}, {"number": "106", "chapter": "الفصل السادس فى الإجازات", "text": "تستمر المحاكم أثناء العطلة القضائية فى نظر الدعاوى التأديبية والمستعجل فى القضايا وتعين هذه القضايا بقرار من رئيس مجلس الدولة وتنظم الجمعية العمومية لكل محكمة العمل أثناء العطلة القضائية فتعين عدد الجلسات وأيام انعقادها ومن يقوم من الأعضاء بالعمل فيها ، ويصدر بذلك قرار من رئيس المجلس ."}, {"number": "107", "chapter": "الفصل السادس فى الإجازات", "text": "لايرخص لأعضاء المحاكم فى إجازات فى غير العطلة القضائية إلا لمن قام منهم بالعمل خلالها وكانت حالة العمل تسمح بذلك ، ومع هذا يجوز الترخيص فى إجازات لظروف استثنائية فى الحدود التى تقررها القوانين واللوائح الخاصة بإجازات العاملين المدنيين بالدولة"}, {"number": "108", "chapter": "الفصل السادس فى الإجازات", "text": "لايجوز أن تزيد مدة الإجازة السنوية بمرتب كامل لأعضاء مجلس الدولة على شهرين بالنسبة للمستشارين ، وشهر ونصف بالنسبة إلى من عداهم ، وتحدد الجمعيات العمومية للمحاكم توزيع الإجازات بين أعضائها"}, {"number": "109", "chapter": "الفصل السادس فى الإجازات", "text": "تكون مدة الأجازات فى السنة الأولى من خدمة العضو خمسة عشر يوما ولا تمنح إلا بعد انقضاء ستة أشهر على أول تعيين ومع ذلك يجوز عند الضرورة وبموافقة رئيس المجلس منح العضو إجازة اعتيادية لمدة أسبع خلال الأشهر الستة الأولى من خدمته على أن تخصم من الإجازة السنوية المستحقة له . ويجوز ضم مدد الإجازة السنوية إلى بعضها بشرط ألا تزيد فى أية سنة على ثلاثة أشهر إلا فى حالة المرض فلا تزيد على ثلاثة أشهر وتحدد مواعيد الإجازة السنوية حسب مقتضيات العمل وظروفه ، ولا يجوز تقصيرها أو تأجيلها أو قطعها أو إلغائها إلا لأسباب قوية تقتضيها مصلحة العمل ."}, {"number": "110", "chapter": "الفصل السادس فى الإجازات", "text": "تكون الأجازات المرضية التى يحصل عليها الأعضاء بمرتب كامل لمدة مجموعها سنة كل ثلاثة سنوات وإذا لم يستطع العضو العودة إلى عمله بعد انقضاء السنة جاز للمجلس الخاص للشئون الإدارية أن يرخص له فى امتداد الإجازة لمدة سنة أخرى بثلاثة أرباع المرتب . وللعضو فى حالة المرض أن يستنفذ ، متجمد إجازاته الاعتيادية بجانب ما يستحقه من إجازاته المرضية . وذلك كله مع عدم الإخلال بأى قانون أصلح ."}, {"number": "111", "chapter": "الفصل السادس فى الإجازات", "text": "ينظم رئيس مجلس الدولة بقرار منه بعد موافقة المجلس الخاص للشئون الإدارية ، الخدمات الصحية والاجتماعات لأعضاء المجلس وشروطها ، وللعضو الذى يصاب بجرح أو عاهة أو مرض أثناء تأدية الوظيفة أو بسببها استرداد مصاريف العلاج التى يعتمدها القومسيون الطبى وذلك بقرار من رئيس مجلس الدولة ."}, {"number": "112", "chapter": "الفصل السابع", "text": "يختص بتأديب أعضاء مجلس الدولة مجلس تأديب يشكل كالآتي : رئيس مجلس الدولة رئيساً ستة من نواب رئيس مجلس الدولة بحسب ترتيب الأقدمية أعضاء وعند خلو وظيفة رئيس المجلس أو غيابه أو وجود مانع لديه يحل محله الأقدم فالأقدم من نوابه ، وكذلك الحكم بالنسبة لأعضاء مجلس التأديب فيحل محل كل منهم من يليه فى الأقدمية من نواب الرئيس ثم من المستشارين ."}, {"number": "113", "chapter": "الفصل السابع", "text": "تقام الدعوى التأديبية من نائب رئيس مجلس الدولة لإدارة التفتيش الفنى بناء على تحقيق جنائي أو بناء على تحقيق إدارى يتولاه أحد نواب رئيس المجلس بالنسبة إلى المستشارين ومستشار بالنسبة إلى باقى أعضاء المجلس ويصدر بندب من يتولى التحقيق قرار من رئيس مجلس الدولة ويجب أن تشتمل عريضة الدعوى على التهمة والأدلة المؤيدة لها وتودع سكرتارية مجلس التأديب ليصدر قراره بإعلان العضو للحضور أمامه ."}, {"number": "114", "chapter": "الفصل السابع", "text": "لمجلس التأديب أن يجرى ما يراه لازما من التحقيقات وله أن يندب أحد أعضائه لهذا الغرض ، ويكون للمجلس أو من يندبه السلطة المخولة لمحاكم الجنح بالنسبة للشهود الذين يرى وجها لسماع أقوالهم ."}, {"number": "115", "chapter": "الفصل السابع", "text": "إذا رأى مجلس التأديب وجها للسير فى إجراءات المحاكمة عن جميع التهم أو بعضها كلف العضو بالحضور بميعاد أسبع على الأقل بناء على أمر من رئيس المجلس ."}, {"number": "116", "chapter": "الفصل السابع", "text": "عند تقرير السير فى إجراءات المحاكمة يجوز لمجلس التأديب أن يأمر بوقف العضو عن مباشرة أعمال وظيفته أو أن يقرر اعتباره فى إجازة حتمية حتى تنتهى المحاكمة ، وللمجلس فى كل وقت أن يعيد النظر فى أمر الوقف أو الإجازة المذكورة . ولايترتب على وقف العضو وقف مرتبه مدة الوقف إلا إذا قرر مجلس التأديب غير ذلك ."}, {"number": "117", "chapter": "الفصل السابع", "text": "تنقضى الدعوى التأديبية باستقالة العضو أو إحالته إلى المعاش ولا تأثير للدعوى التأديبية على الدعوى الجنائية أو المدنية الناشئة عن الواقعة ذاتها ."}, {"number": "118", "chapter": "الفصل السابع", "text": "تكون جلسات المحاكمة التأديبية سرية . ويحكم مجلس التأديب فى الدعوى بعد سماع رأى إدارة التفتيش الفنى ودفاع العضو ويكون العضو آخر من يتكلم . ويحضر العضو بشخصه أمام المجلس وله أن يقدم دفاعه كتابة أو ينوب عنه أحد أعضاء مجلس الدولة فى الدفاع عنه . وللمجلس دائما الحق فى طلب حضور العضو بشخصه . وإذا لم يحضر العضو أو لم ينب عنه أحدا جاز الحكم فى غيبته بعد التحقق من صحة إعلانه ."}, {"number": "119", "chapter": "الفصل السابع", "text": "يجب أن يكون الحكم الصادر فى الدعوى التأديبية مشتملا على الأسباب التى بنى عليها وأن تتلى عند النطق به فى جلسة سرية . ويكون الحكم الصادر فى الدعوى التأديبية نهائيا غير قابل للطعن فيه بأى طريق من طرق الطعن ."}, {"number": "120", "chapter": "الفصل السابع", "text": "العقوبات التأديبية التى يجوز توقيعها على أعضاء مجلس الدولة هى : اللوم – والعزل : وإذا صدر هنا حكم مجلس التأديب بعقوبة العزل اعتبر عضو المجلس فى إجازة حتمية من تاريخ صدور الحكم إلى يوم نشر منطوقة فى الجريدة الرسمية ، ويعتبر تاريخ العزل من يوم النشر فى الجريدة الرسمية . أما عقوبة اللوم فيصدر بتنفيذها قرار من رئيس مجلس الدولة ، ولا ينشر هذا القرار أو منطوق الحكم فى الجريدة الرسمية ."}, {"number": "121", "chapter": "الفصل السابع", "text": "يترتب حتما على حبس عضو مجلس الدولة بناء على أمر أو حكم وقفه عن مباشرة أعمال وظيفته مدة حبسه . ويجوز لمجلس التأديب أن يأمر بوقف العضو عن مباشرة أعمال وظيفته أثناء إجراءات التحقيق أو المحاكمة عن جريمة وقعت منه ، وذلك من تلقاء ذاته أو بناء على طلب رئيس مجلس الدولة ولا يترتب على وقف العضو وقف صرف مرتبه مدة الوقف ما لم يقرر المجلس المذكور وقف صرف نصف المرتب ، وله فى كل وقت أن يعيد النظر فى أمر الوقف والمرتب ."}, {"number": "122", "chapter": "الفصل الثامن فى مرتبات أعضاء مجلس الدولة ومعاشاتهم", "text": "تحدد مرتبات أعضاء مجلس الدولة بجميع درجاتهم وفقا للجدول الملحق بهذا القانون ، ولا يصح أن يقرر لأحد منهم مرتب بصفة شخصية أو أن يعامل معاملة استثنائية بأية صورة . وتسرى فيما يتعلق بهذه المرتبات والبدلات والمزايا الأخرى وكذلك بالمعاشات وبنظامها جميع الأحكام التى تقرر فى شأن الوظائف المماثلة بقانون السلطة القضائية ."}, {"number": "123", "chapter": "الفصل الثامن فى مرتبات أعضاء مجلس الدولة ومعاشاتهم", "text": "استثناء من أحكام قوانين المعاشات لا يجوز أن يبقى أو يعين عضوا بمجلس الدولة من جاوز عمره ستين سنة ميلادية . ومع ذلك إذا كان بلوغ العضو سن التقاعد فى الفترة من أول أكتوبر إلى أول يوليو فإنه يبقى فى الخدمة حتى هذا التاريخ دون أن تحتسب هذه المدة فى تقدير المعاش أو المكافأة ."}, {"number": "124", "chapter": "الفصل الثامن فى مرتبات أعضاء مجلس الدولة ومعاشاتهم", "text": "تعتبر استقالة عضو مجلس الدولة مقبولة من تاريخ تقديمها إلى رئيس المجلس إذا كانت غير مقترنة بقيد أو معلقة على شرط . واستثناء من أحكام قوانين المعاشات لا يترتب على استقالة عضو المجلس سقوط حقه فى المعاش أو المكافأة أو خفضهما . وفى جميع حالات انتهاء الخدمة يسوى معاش العضو أو مكافأته على أساس آخر مربوط الوظيفة التى كان يشغلها أو آخر مرتب كان يتقاضاه أيهما أصلح له ووفقا للقواعد المقررة بالنسبة للموظفين الذين تنتهى خدمتهم بسبب إلغاء الوظيفة أو الوفر"}, {"number": "125", "chapter": "الفصل الثامن فى مرتبات أعضاء مجلس الدولة ومعاشاتهم", "text": "إذا لم يستطع عضو مجلس الدولة بسبب مرضه مباشرة عمله بعد انقضاء الإجازات المقررة فى المادة 110 أو ظهر فى أى وقت أنه لا يستطيع لأسباب صحية القيام بوظيفته على الوجه اللائق أحيل إلى المعاش بقرار من رئيس الجمهورية يصدر بناء على طلب رئيس مجلس الدولة وبعد موافقة المجلس الخاص للشئون الإدارية . ويجوز للمجلس المذكور فى هذه الحالة أن يزيد على خدمة العضو المحسوبة فى المعاش أو المكافأة مدة إضافية بصفة استثنائية على ألا تجاوز هذه المدة الإضافية مدة الخدمة ولا المدة الباقية لبلوغ السن المقررة للإحالة للمعاش ، كما لا يجوز أن تزيد تلك المدة على ثمانى سنوات ولا أن يكون من شأنها أن تعطيه حقا فى معاش يزيد على أربعة أخماس مرتبه . ومع ذلك لا يجوز أن يقل المعاش عن أربعة أخماس آخر مرتب كان يتقاضاه العضو أو يستحقه عند انتهاء خدمته إذا كانت مدة الخدمة المحسوبة فى المعاش لا تقل عن عشرين سنة . وتسرى أحكام الفقرتين السابقتين فى حالة الوفاة . وفى جميع الأحوال لا يجوز أن يزيد المعاش على الحد الأقصى المقرر بمقتضى قوانين المعاشات ."}, {"number": "126", "chapter": "الباب الخامس الوظائف الإدارية والكتابية", "text": "يكون لرئيس مجلس الدولة سلطة الوزير المنصوص عليها فى القوانين واللوائح بالنسبة إلى العاملين من شاغلي الوظائف الإدارية والكتابية . كما يكون لأمين عام المجلس بالنسبة إلى هؤلاء سلطة وكيل الوزارة أو رئيس المصلحة بحسب الأحوال ."}, {"number": "127", "chapter": "الباب الخامس الوظائف الإدارية والكتابية", "text": "يجوز تعيين الحاصلين على درجة الليسانس من إحدى الكليات الحقوق بإحدى الجامعات بجمهورية مصر العربية والحاصلين على هذه الدرجة من كليات أجنبية معترف بها مع شهادة المعادلة فى الوظائف الإدارية ويلحق هؤلاء بالقسم أو قسمي الفتوى والتشريع أو المكتب الفنى ويجوز أن يعين من هؤلاء فى وظيفة مندوب بالمجلس من يظهر كفاية ممتازة في عمله ويحصل على المؤهلات اللازمة للتعيين فى هذه الوظيفة ."}, {"number": "128", "chapter": "الباب الخامس الوظائف الإدارية والكتابية", "text": "يكون التعيين فى الوظائف الكتابية بالمجلس بعد امتحان مسابقة يجريه المجلس للمرشحين طبقاً للنظام الذي تحدده اللائحة الداخلية للمجلس."}, {"number": "129", "chapter": "الباب الخامس الوظائف الإدارية والكتابية", "text": "يجوز أن يندب العاملون بالوزارات ووحدات الحكم المحلى والهيئات العامة فى الوظائف الكتابية بالمجلس وذلك بالاتفاق بين الجهة المختصة وبين رئيس مجلس الدولة . ويكون لأمين عام المجلس سلطات وكيل الوزارة أو رئيس المصلحة حسب الأحوال بالنسبة لهؤلاء العاملين أثناء مدة ندبهم . جدول الوظائف والمرتبات والبدلات المحلق بالقانون رقم 47 لسنة 1972 بشأن مجلس الدولة الوظائف المخصصات السنوية العلاوة الدورية السنوية المرتب بدل قضاء بدل تمثيل رئيس مجلس الدولة............. جنيه 2928 جنيه ـ جنيه 2000 جنيه ربط ثابت نواب رئيس مجلس الدولة........ 2380 – 2868 ـ 1500 100 وكلاء مجلس الدولة.............. 2180 – 2493 ـ 200 75 المستشارون...................... 1680 – 2433 450 ـ 75 المستشارون المساعدون فئة (أ)... 1608 – 2364 424.8 ـ 72 المستشارون المساعدون فئة (ب).. 1368 – 2064 356.4 ـ 72 النواب........................... 1140 – 1868 288 تزاد إلي 324 إذا بلغ المرتب 1080 ـ 60 المندوبون........................ 840 – 1464 198 ـ 48 المندوبون المساعدون............ 648 - 900 129.6 ـ 36"}]};